/* Fleet Autopilot UI demo. All records and actions stay in this browser. */
(() => {
  'use strict';
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const key='fleet-autopilot-workspace-v2',sampleDay='2026-11-16';
  const stamp=()=>new Date().toISOString();
  const time=value=>value?new Date(value).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Bangkok'}):'—';
  const date=value=>value?value.split('-').reverse().join('/'):'—';
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm=v=>String(v??'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');
  const icon=name=>`<svg aria-hidden="true"><use href="#${name}"/></svg>`;
  const labels={pending:'Chờ phân xe',assigned:'Đã phân công',running:'Đang chạy',completed:'Hoàn thành',cancelled:'Đã hủy',ready:'Sẵn sàng',maintenance:'Bảo trì',fresh:'Có tín hiệu mẫu',stale:'Chưa cập nhật',offline:'Mất tín hiệu mẫu',active:'Đang làm việc',off:'Tạm nghỉ'};
  const badge=(status,text)=>`<span class="badge" data-status="${status==='ready'||status==='fresh'||status==='active'?'completed':status==='stale'||status==='maintenance'||status==='off'?'pending':status==='offline'||status==='cancelled'?'neutral':status}"><span class="status-dot" aria-hidden="true"></span><span>${esc(text||labels[status]||status)}</span></span>`;
  function seed(){return {version:2,selectedOrder:'ĐH-1045',selectedVehicle:'51C-732.18',settings:{company:'Fleet Autopilot',dispatcher:'Điều phối viên',toasts:true,motion:true},
    drivers:['An','Bình','Châu','Dũng','Giang','Hải'].map((name,i)=>({id:'TX-'+(i+1),name:'Tài xế '+name+' (mẫu)',phone:'',status:'active'})),
    vehicles:[['51C-732.18',30,18,'ready','fresh',95,205],['51D-110.46',32,21,'ready','fresh',220,145],['51C-905.27',35,24,'ready','fresh',370,225],['51C-481.66',30,16,'ready','stale',455,112],['51D-218.09',25,27,'ready','fresh',290,75],['51C-660.25',30,30,'maintenance','offline',535,235]].map((v,i)=>({plate:v[0],capacity:v[1],eta:v[2],availability:v[3],gps:v[4],x:v[5],y:v[6],driverId:'TX-'+(i+1),type:'Xe ben',updated:'2026-11-16T03:20:00.000Z'})),
    orders:[
      {id:'ĐH-1046',customer:'Công trình Bình An (mẫu)',material:'Đá 1×2',quantity:20,from:'Mỏ Long Phước',to:'Công trình Bình An',day:sampleDay,slot:'14:00',status:'pending',plate:'',note:''},
      {id:'ĐH-1045',customer:'Công trình Q.9 (mẫu)',material:'Cát xây dựng',quantity:30,from:'Mỏ Tân Hòa',to:'Công trình Q.9',day:sampleDay,slot:'10:30',status:'pending',plate:'',note:''},
      {id:'ĐH-1044',customer:'Công trình Q.2 (mẫu)',material:'Đá 1×2',quantity:25,from:'Mỏ Tân Hòa',to:'Công trình Q.2',day:sampleDay,slot:'10:00',status:'running',plate:'51C-481.66',note:''},
      {id:'ĐH-1043',customer:'Công trình Q.9 (mẫu)',material:'Cát san lấp',quantity:20,from:'Mỏ Long Phước',to:'Công trình Q.9',day:sampleDay,slot:'09:00',status:'completed',plate:'51D-110.46',note:''},
      {id:'ĐH-1042',customer:'Công trình Thủ Đức (mẫu)',material:'Đất đắp',quantity:30,from:'Mỏ Phước Bình',to:'Thủ Đức',day:'2026-11-15',slot:'16:00',status:'completed',plate:'51C-905.27',note:''}
    ],activity:[{text:'Hoàn thành đơn ĐH-1043',detail:'Đã giao 20 tấn cát san lấp trong dữ liệu mẫu.',at:'2026-11-16T02:57:00.000Z'},{text:'Xe 51C-481.66 đang chạy đơn ĐH-1044',detail:'Mỏ Tân Hòa → Công trình Q.2',at:'2026-11-16T03:24:00.000Z'}]};}
  function valid(s){return s?.version===2&&Array.isArray(s.orders)&&Array.isArray(s.vehicles)&&Array.isArray(s.drivers)&&Array.isArray(s.activity)&&s.settings&&s.orders.every(o=>o&&typeof o.id==='string'&&typeof o.material==='string'&&Number.isFinite(o.quantity)&&o.quantity>0&&['pending','assigned','running','completed','cancelled'].includes(o.status)&&typeof o.day==='string')&&s.vehicles.every(v=>v&&typeof v.plate==='string'&&Number.isFinite(v.capacity)&&Number.isFinite(v.x)&&Number.isFinite(v.y))&&s.drivers.every(d=>d&&typeof d.id==='string'&&typeof d.name==='string');}
  let state=seed(),storageFailed=false;
  try{const saved=JSON.parse(localStorage.getItem(key));if(valid(saved))state=saved;else{const old=JSON.parse(localStorage.getItem('fleet-autopilot-ui-demo-v1'));if(old?.selected&&state.vehicles.some(v=>v.plate===old.selected)){state.selectedVehicle=old.selected;if(old.assigned){const o=state.orders.find(o=>o.id==='ĐH-1045');o.status='assigned';o.plate=old.selected;}}}}catch{}
  const routes={overview:'Tổng quan',orders:'Đơn hàng',dispatch:'Điều phối',fleet:'Xe & tài xế',gps:'GPS',reports:'Báo cáo',settings:'Cài đặt'};
  const routeKeys=Object.keys(routes),navToRoute=Object.fromEntries(Object.entries(routes).map(([k,v])=>[v,k]));
  let page=routeKeys.includes(new URLSearchParams(location.search).get('page'))?new URLSearchParams(location.search).get('page'):'dispatch';
  let orderQuery='',orderStatus='all',orderDay='',fleetQuery='',fleetFilter='all',fleetTab='vehicles',gpsFilter='all',gpsPlate=state.vehicles[0]?.plate,gpsZoom=1,mapZoom=1;
  let reportFrom='2026-11-10',reportTo=sampleDay,toastTimer,onConfirm=null;
  const modal=$('#modal'),title=$('#modal-title'),copy=$('#modal-copy'),content=$('#modal-content'),confirm=$('#confirm-modal'),searchModal=$('#search-modal');
  function toast(text){if(!state.settings.toasts)return;clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3200);}
  function formError(text){const el=$('#editor-error')||$('#preferences-error');if(el){el.hidden=false;el.textContent=text;}}
  function save(){try{localStorage.setItem(key,JSON.stringify(state));storageFailed=false;}catch{storageFailed=true;$('#toast').hidden=false;$('#toast').textContent='Trình duyệt chưa lưu được dữ liệu. Thay đổi hiện chỉ ở phiên này.';}}
  function log(text,detail=''){state.activity.unshift({text,detail,at:stamp()});state.activity=state.activity.slice(0,60);}
  function commit(text,detail=''){if(text)log(text,detail);save();render();window.dispatchEvent(new CustomEvent('fleet:commit',{detail:{text,detail,actor:state.settings.dispatcher}}));}
  function order(id){return state.orders.find(o=>o.id===id);}
  function vehicle(plate){return state.vehicles.find(v=>v.plate===plate);}
  function driver(id){return state.drivers.find(d=>d.id===id);}
  function activeOrder(plate){return state.orders.find(o=>o.plate===plate&&['assigned','running'].includes(o.status));}
  function vehicleStatus(v){return activeOrder(v.plate)?.status||v.availability;}
  function counts(){return {pending:state.orders.filter(o=>o.status==='pending').length,running:state.orders.filter(o=>o.status==='running').length,completed:state.orders.filter(o=>o.status==='completed').length,ready:state.vehicles.filter(v=>vehicleStatus(v)==='ready').length};}
  function alerts(){return state.vehicles.flatMap(v=>[...(v.availability==='maintenance'?[{kind:'maintenance',title:v.plate+' đang bảo trì',text:'Kiểm tra trước khi đưa xe trở lại hoạt động.',plate:v.plate}]:[]),...(v.gps==='stale'?[{kind:'stale',title:v.plate+' chưa cập nhật vị trí',text:'Vị trí trong sơ đồ là dữ liệu mẫu.',plate:v.plate}]:[])]);}
  function selectedOrder(){return state.orders.find(o=>o.id===state.selectedOrder&&o.status!=='cancelled')||state.orders.find(o=>o.status==='pending')||state.orders.find(o=>o.status!=='cancelled');}
  function candidates(o){return o?state.vehicles.filter(v=>vehicleStatus(v)==='ready'&&v.capacity>=o.quantity&&driver(v.driverId)?.status==='active').sort((a,b)=>a.eta-b.eta):[];}
  function openModal(name,text,extra=null,action=null,actionLabel='Xác nhận mô phỏng'){
    modal.classList.remove('assignment-review','attention-review');modal.querySelector('.attention-note')?.remove();$('#cancel-modal').textContent='Đóng';confirm.textContent=actionLabel;title.textContent=name;copy.textContent=text;content.replaceChildren();if(extra)content.append(extra);onConfirm=action;confirm.hidden=!action;
    if(!modal.open)modal.showModal();
  }
  function htmlNode(html){const el=document.createElement('div');el.innerHTML=html;return el;}
  function showAttention(){
    const items=alerts().sort((a,b)=>Number(b.kind==='stale')-Number(a.kind==='stale'));
    const rows=items.map(a=>{
      const stale=a.kind==='stale',o=activeOrder(a.plate);
      const context=stale?(o?`Đang thực hiện đơn <strong>${esc(o.id)}</strong> · ${esc(o.from)} → ${esc(o.to)}`:'Chưa có chuyến đang thực hiện.'):'Chưa sẵn sàng nhận phân công.';
      return `<article class="attention-item"><div class="attention-priority${stale?'':' watch'}"><i aria-hidden="true"></i>${stale?'Cần kiểm tra':'Cần theo dõi'}</div><h3>Xe ${esc(a.title)}</h3><p>${context}</p><p>${stale?'Kiểm tra tín hiệu trước khi theo dõi tiến độ giao hàng.':'Kiểm tra tình trạng xe trước khi đưa trở lại hoạt động.'}</p>${actionButton(icon(stale?'pin':'truck')+(stale?'Xem hành trình':'Xem xe')+' <span aria-hidden="true">→</span>',stale?'track-vehicle':'detail-vehicle',a.plate,'attention-link')}</article>`;
    }).join('');
    openModal('Cần xử lý',items.length?'Kiểm tra các vấn đề ảnh hưởng đến điều phối.':'Hiện không có mục cần xử lý trong dữ liệu mẫu.',htmlNode(rows));
    modal.classList.add('attention-review');
    title.insertAdjacentHTML('beforeend',`<span class="attention-count">${items.length} mục</span>`);
    const note=htmlNode(`<span class="attention-note">${icon('alert')}Dữ liệu mô phỏng · Chưa kết nối GPS thực tế</span>`).firstElementChild;
    modal.querySelector('.modal-actions').prepend(note);
  }
  function closeModal(){modal.close();onConfirm=null;}
  $('#close-modal').onclick=closeModal;$('#cancel-modal').onclick=closeModal;
  confirm.onclick=()=>{const action=onConfirm;if(action&&action()===false)return;if(action===reset)window.dispatchEvent(new Event('fleet:reset'));closeModal();};
  modal.addEventListener('close',()=>{onConfirm=null;});
  for(const dialog of [modal,searchModal])dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();});
  function setPage(next,{push=true,focus=false}={}){if(!routeKeys.includes(next))return;page=next;if(push){const url=new URL(location.href);url.searchParams.set('page',next);history.pushState(null,'',url);}render();window.scrollTo(0,0);if(focus)$('#main').focus({preventScroll:true});}
  window.addEventListener('popstate',()=>{const value=new URLSearchParams(location.search).get('page');setPage(routeKeys.includes(value)?value:'dispatch',{push:false});});
  $$('[data-page]').forEach(button=>{button.disabled=false;button.removeAttribute('title');button.onclick=()=>setPage(navToRoute[button.dataset.page],{focus:true});});
  function actionButton(label,action,id,className='text-button'){return `<button class="${className}" data-action="${action}"${id?` data-id="${esc(id)}"`:''}>${label}</button>`;}
  function pageHead(kicker,name,subtitle,actions=''){return `<div class="workspace-head"><div><p class="eyebrow">${kicker}</p><h1>${name}</h1><p>${subtitle}</p></div><div class="workspace-actions">${actions}</div></div>`;}
  function metric(label,value,symbol,action){const tag=action?'button':'div';return `<${tag} class="stat"${action?` data-action="${action}"`:''}><span class="stat-icon">${icon(symbol)}</span><span>${label}<strong>${value}</strong></span></${tag}>`;}
  function empty(text,action=''){return `<div class="empty-state">${icon('order')}<strong>${text}</strong><p>Thử thay đổi bộ lọc hoặc thêm dữ liệu mẫu.</p>${action}</div>`;}
  function timeline(limit=5){return `<ol class="timeline workspace-timeline">${[...state.activity].sort((a,b)=>new Date(b.at)-new Date(a.at)).slice(0,limit).map(a=>`<li><div><strong>${esc(a.text)}</strong><p>${esc(a.detail)}</p></div><time>${time(a.at)}</time></li>`).join('')}</ol>`;}
  function orderRows(list,compact=false){return list.map(o=>`<tr><td>${actionButton(esc(o.id),'detail-order',o.id)}<small>${esc(o.customer)}</small></td><td>${esc(o.material)}<small>${o.quantity} tấn</small></td><td><span class="route-cell">${esc(o.from)} <span>→</span> ${esc(o.to)}</span></td>${compact?'':`<td>${date(o.day)}<small>${esc(o.slot||'Chưa đặt giờ')}</small></td>`}<td>${badge(o.status)}</td><td>${o.status==='pending'?actionButton('Phân xe →','dispatch-order',o.id):actionButton('Chi tiết →','detail-order',o.id)}</td></tr>`).join('');}
  function ordersTable(list,compact=false){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Đơn hàng / khách</th><th>Vật liệu</th><th>Hành trình</th>${compact?'':'<th>Lịch giao mẫu</th>'}<th>Trạng thái</th><th><span class="sr-only">Thao tác</span></th></tr></thead><tbody>${orderRows(list,compact)}</tbody></table></div>`;}
  function overview(){const c=counts(),a=alerts(),active=state.orders.filter(o=>!['completed','cancelled'].includes(o.status));return pageHead('KHÔNG GIAN VẬN HÀNH','Tổng quan vận chuyển','Theo dõi đơn hàng, đội xe và việc cần làm trong dữ liệu mẫu.',actionButton('Tạo đơn hàng','new-order',null,'primary'))+
    `<div class="stats workspace-stats">${metric('Chờ phân xe',c.pending,'order','go-orders-pending')}${metric('Chuyến đang chạy',c.running,'truck','go-gps')}${metric('Xe sẵn sàng',c.ready,'truck','go-fleet')}${metric('Đã hoàn thành',c.completed,'layers','go-reports')}</div><div class="workspace-columns"><section class="panel"><div class="panel-heading"><h2>${icon('order')}Đơn cần theo dõi</h2>${actionButton('Tất cả đơn →','go-orders')}</div>${active.length?ordersTable(active,true):empty('Chưa có đơn đang xử lý.')}</section><section class="panel attention-panel"><div class="panel-heading"><h2>${icon('alert')}Cần chú ý</h2><span class="count-label">${a.length} mục mẫu</span></div>${a.map(item=>`<button class="attention-row" data-action="detail-vehicle" data-id="${esc(item.plate)}"><span class="attention-dot"></span><span><strong>${esc(item.title)}</strong><small>${esc(item.text)}</small></span><span>↗</span></button>`).join('')||'<p class="subtle">Không có mục cần chú ý.</p>'}<p class="section-note">Các cảnh báo minh họa, chưa nhận dữ liệu từ thiết bị GPS.</p></section></div><div class="workspace-columns equal"><section class="panel"><div class="panel-heading"><h2>${icon('chart')}Tình hình đơn hàng</h2><span class="subtle">Toàn bộ dữ liệu mẫu</span></div>${['pending','assigned','running','completed','cancelled'].map(s=>{const n=state.orders.filter(o=>o.status===s).length;return `<div class="distribution-row"><span>${labels[s]}</span><div class="bar-track"><i style="width:${state.orders.length?n/state.orders.length*100:0}%"></i></div><strong>${n}</strong></div>`}).join('')}</section><section class="panel"><div class="panel-heading"><h2>${icon('activity')}Hoạt động gần đây</h2><span class="subtle">Lưu trong trình duyệt</span></div>${timeline(4)}</section></div>`;}
  function ordersView(){const list=state.orders.filter(o=>(orderStatus==='all'||o.status===orderStatus)&&(!orderDay||o.day===orderDay)&&norm(Object.values(o).join(' ')).includes(norm(orderQuery)));return pageHead('QUẢN LÝ VẬN CHUYỂN','Đơn hàng','Tiếp nhận, xem chi tiết và chuyển đơn sang màn Điều phối.',actionButton('Xuất CSV','export-orders',null,'secondary')+actionButton('+ Tạo đơn hàng','new-order',null,'primary'))+
    `<section class="panel"><div class="filter-bar"><label class="field search-field"><span>Tìm đơn hàng</span><input id="orders-query" type="search" placeholder="Mã đơn, khách, vật liệu, hành trình…" value="${esc(orderQuery)}"></label><label class="field"><span>Trạng thái</span><select id="orders-status"><option value="all">Tất cả trạng thái</option>${Object.entries(labels).filter(([k])=>['pending','assigned','running','completed','cancelled'].includes(k)).map(([k,v])=>`<option value="${k}" ${orderStatus===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>Ngày giao mẫu</span><input id="orders-day" type="date" value="${esc(orderDay)}"></label>${actionButton('Xóa lọc','clear-order-filters',null,'secondary')}</div><div class="results-heading"><strong>${list.length} đơn hàng</strong><span>Dữ liệu mẫu · Khối lượng tính bằng tấn</span></div>${list.length?ordersTable(list):empty('Không tìm thấy đơn phù hợp.',actionButton('Tạo đơn mới','new-order',null,'secondary'))}<p class="section-note">Có thể cuộn ngang bảng trên màn hình nhỏ.</p></section>`;}
  function fleetView(){const vehicles=state.vehicles.filter(v=>(fleetFilter==='all'||vehicleStatus(v)===fleetFilter)&&norm(v.plate+' '+(driver(v.driverId)?.name||'')+' '+v.type).includes(norm(fleetQuery)));const drivers=state.drivers.filter(d=>norm(d.name+' '+d.id+' '+d.phone).includes(norm(fleetQuery)));return pageHead('NGUỒN LỰC VẬN CHUYỂN','Xe & tài xế','Quản lý thông tin mẫu của đội xe và người thực hiện chuyến.',actionButton(fleetTab==='vehicles'?'+ Thêm xe':'+ Thêm tài xế',fleetTab==='vehicles'?'new-vehicle':'new-driver',null,'primary'))+
    `<div class="tabs" role="group" aria-label="Nhóm nguồn lực"><button id="fleet-tab-vehicles" aria-pressed="${fleetTab==='vehicles'}" data-action="fleet-tab" data-id="vehicles">Đội xe <span>${state.vehicles.length}</span></button><button id="fleet-tab-drivers" aria-pressed="${fleetTab==='drivers'}" data-action="fleet-tab" data-id="drivers">Tài xế <span>${state.drivers.length}</span></button></div><section class="panel"><div class="filter-bar"><label class="field search-field"><span>Tìm ${fleetTab==='vehicles'?'xe / tài xế':'tài xế'}</span><input id="fleet-query" type="search" placeholder="Biển số hoặc tên…" value="${esc(fleetQuery)}"></label>${fleetTab==='vehicles'?`<label class="field"><span>Tình trạng xe</span><select id="fleet-status"><option value="all">Tất cả</option>${['ready','assigned','running','maintenance'].map(s=>`<option value="${s}" ${fleetFilter===s?'selected':''}>${labels[s]}</option>`).join('')}</select></label>`:''}<span class="filter-spacer"></span>${actionButton('Xuất CSV',fleetTab==='vehicles'?'export-fleet':'export-drivers',null,'secondary')}</div>${fleetTab==='vehicles'?(vehicles.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Xe / loại</th><th>Tải mẫu</th><th>Tài xế</th><th>Tình trạng</th><th>GPS mẫu</th><th>Thao tác</th></tr></thead><tbody>${vehicles.map(v=>`<tr><td>${actionButton(esc(v.plate),'detail-vehicle',v.plate)}<small>${esc(v.type)}</small></td><td>${v.capacity} tấn</td><td>${esc(driver(v.driverId)?.name||'Chưa gán tài xế')}</td><td>${badge(vehicleStatus(v))}</td><td>${badge(v.gps)}</td><td>${actionButton('Chỉnh sửa','edit-vehicle',v.plate)}</td></tr>`).join('')}</tbody></table></div>`:empty('Không có xe phù hợp.')):(drivers.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Tài xế</th><th>Xe đang gắn</th><th>Liên hệ</th><th>Tình trạng</th><th>Thao tác</th></tr></thead><tbody>${drivers.map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${esc(d.id)}</small></td><td>${esc(state.vehicles.find(v=>v.driverId===d.id)?.plate||'Chưa gắn xe')}</td><td>${esc(d.phone||'Chưa có')}</td><td>${badge(d.status)}</td><td>${actionButton('Chỉnh sửa','edit-driver',d.id)}</td></tr>`).join('')}</tbody></table></div>`:empty('Không có tài xế phù hợp.'))}<p class="section-note">Thông tin tải trọng và tình trạng đang dùng để thử giao diện, chưa thay cho kiểm tra vận hành thực tế.</p></section>`;}
  function gpsView(){const list=state.vehicles.filter(v=>gpsFilter==='all'||v.gps===gpsFilter);if(!list.some(v=>v.plate===gpsPlate))gpsPlate=list[0]?.plate;const v=vehicle(gpsPlate),o=v?activeOrder(v.plate):null;return pageHead('THEO DÕI HÀNH TRÌNH','GPS & vị trí xe','Sơ đồ mô phỏng · Chưa kết nối bản đồ hoặc thiết bị GPS.',actionButton('Cập nhật vị trí mẫu','simulate-gps',null,'secondary'))+
    `<div class="gps-workspace"><section class="panel gps-list"><div class="panel-heading"><h2>${icon('truck')}Đội xe</h2><span class="count-label">${list.length} xe</span></div><label class="field"><span>Lọc tín hiệu mẫu</span><select id="gps-filter"><option value="all">Tất cả tín hiệu</option>${['fresh','stale','offline'].map(s=>`<option value="${s}" ${gpsFilter===s?'selected':''}>${labels[s]}</option>`).join('')}</select></label><div class="gps-vehicle-list">${list.map(x=>`<button id="gps-list-${esc(encodeURIComponent(x.plate))}" class="gps-vehicle ${x.plate===gpsPlate?'selected':''}" aria-pressed="${x.plate===gpsPlate}" data-action="gps-select" data-id="${esc(x.plate)}"><span><strong>${esc(x.plate)}</strong><small>${esc(driver(x.driverId)?.name||'Chưa có tài xế')}</small></span>${badge(x.gps)}</button>`).join('')||'<p class="subtle">Không có xe phù hợp.</p>'}</div></section><section class="panel"><div class="panel-heading"><h2>${icon('pin')}Sơ đồ vị trí mẫu</h2><span class="subtle">Không phải bản đồ thực tế</span></div><div class="map workspace-map"><svg class="fleet-map" viewBox="0 0 620 300" role="group" aria-label="Sơ đồ minh họa vị trí các xe trong dữ liệu mẫu"><rect width="620" height="300"/><g class="map-roads" fill="none"><path d="M-20 90 170 10 350 90 650 20M0 210 160 130 360 200 650 120M100 0 220 300M240-20 370 300M390 0 520 300M530-20 650 230M-20 270 220 170 470 280 640 210M0 145 180 70 460 150 620 85"/></g><path class="map-river" d="M330-20C300 60 450 25 385 95S470 165 440 220 400 260 455 330" fill="none"/>${list.map(x=>`<g id="gps-marker-${esc(encodeURIComponent(x.plate))}" role="button" tabindex="0" aria-label="Chọn xe ${esc(x.plate)}" data-action="gps-select" data-id="${esc(x.plate)}" class="fleet-marker ${x.plate===gpsPlate?'chosen':''}" transform="translate(${x.x},${x.y})"><circle r="${x.plate===gpsPlate?9:6}"/><rect x="-41" y="14" width="82" height="20" rx="4"/><text text-anchor="middle" y="27">${esc(x.plate)}</text></g>`).join('')}</svg><div class="map-tools"><button data-action="gps-in" aria-label="Phóng to sơ đồ" ${gpsZoom>=1.6?'disabled':''}>+</button><button data-action="gps-out" aria-label="Thu nhỏ sơ đồ" ${gpsZoom<=1?'disabled':''}>−</button></div><span class="map-caption">Vị trí mẫu để xem thử giao diện</span></div>${v?`<div class="gps-summary"><div><span class="review-label">Xe đang chọn</span><strong>${esc(v.plate)}</strong></div><div><span class="review-label">Đơn đang thực hiện</span><strong>${o?esc(o.id):'Chưa có chuyến'}</strong></div><div><span class="review-label">Cập nhật mẫu</span><strong>${time(v.updated)}</strong></div>${actionButton('Chi tiết xe →','detail-vehicle',v.plate)}</div>`:'<p class="subtle">Chọn bộ lọc khác để xem xe.</p>'}</section></div>`;}
  function reportData(){return state.orders.filter(o=>o.day>=reportFrom&&o.day<=reportTo);}
  function reportsView(){const list=reportData(),done=list.filter(o=>o.status==='completed'),weight=done.reduce((n,o)=>n+o.quantity,0),days=[...new Set(list.map(o=>o.day))].sort(),max=Math.max(1,...days.map(day=>list.filter(o=>o.day===day).length));const materials=[...new Set(list.map(o=>o.material))];return pageHead('HIỆU QUẢ VẬN CHUYỂN','Báo cáo','Tổng hợp từ các đơn hàng mẫu trong khoảng ngày bạn chọn.',actionButton('Xuất báo cáo CSV','export-reports',null,'primary'))+
    `<section class="panel report-filters"><div class="filter-bar"><label class="field"><span>Từ ngày</span><input id="report-from" type="date" value="${esc(reportFrom)}"></label><label class="field"><span>Đến ngày</span><input id="report-to" type="date" value="${esc(reportTo)}"></label><p class="subtle">Ngày minh họa: ${date(sampleDay)} · Không có dữ liệu tài chính.</p></div>${reportFrom>reportTo?'<p class="form-error" role="alert">Ngày bắt đầu phải trước hoặc bằng ngày kết thúc.</p>':''}</section><div class="stats workspace-stats">${metric('Tổng đơn trong kỳ',list.length,'order')}${metric('Đơn hoàn thành',done.length,'layers')}${metric('Khối lượng đã giao',weight+' t','truck')}${metric('Tỷ lệ hoàn thành',list.length?Math.round(done.length/list.length*100)+'%':'—','chart')}</div><div class="workspace-columns equal"><section class="panel"><div class="panel-heading"><h2>${icon('chart')}Đơn theo ngày</h2><span class="subtle">Theo ngày giao mẫu</span></div>${days.length?`<div class="report-bars" role="img" aria-label="${esc(days.map(day=>date(day)+': '+list.filter(o=>o.day===day).length+' đơn').join('; '))}">${days.map(day=>`<div><strong>${list.filter(o=>o.day===day).length}</strong><div class="vertical-track"><i style="height:${list.filter(o=>o.day===day).length/max*100}%"></i></div><span>${date(day).slice(0,5)}</span></div>`).join('')}</div>`:empty('Chưa có dữ liệu trong kỳ.')}</section><section class="panel"><div class="panel-heading"><h2>${icon('layers')}Khối lượng theo vật liệu</h2><span class="subtle">Tổng đơn trong kỳ</span></div>${materials.map(m=>{const q=list.filter(o=>o.material===m).reduce((n,o)=>n+o.quantity,0),total=list.reduce((n,o)=>n+o.quantity,0);return `<div class="material-row"><div><strong>${esc(m)}</strong><span>${q} tấn</span></div><div class="bar-track"><i style="width:${total?q/total*100:0}%"></i></div></div>`}).join('')||'<p class="subtle">Không có dữ liệu.</p>'}<p class="section-note">Tỷ lệ hoàn thành = số đơn hoàn thành / tổng số đơn trong kỳ.</p></section></div><section class="panel"><div class="panel-heading"><h2>${icon('order')}Chi tiết trong kỳ</h2><span class="count-label">${list.length} đơn</span></div>${list.length?ordersTable(list):empty('Không có đơn trong kỳ đã chọn.')}</section>`;}
  function settingsView(){const s=state.settings;return pageHead('KHÔNG GIAN LÀM VIỆC','Cài đặt','Tùy chỉnh giao diện và dữ liệu mẫu trên trình duyệt này.')+`<div class="settings-grid"><form id="preferences-form" class="panel"><div class="panel-heading"><h2>${icon('gear')}Thông tin hiển thị</h2></div><label class="field"><span>Tên không gian</span><input name="company" value="${esc(s.company)}" maxlength="60" required></label><label class="field"><span>Tên người điều phối</span><input name="dispatcher" value="${esc(s.dispatcher)}" maxlength="60" required></label><p class="section-note">Chỉ thay đổi tên hiển thị trong bản thử, chưa phải hồ sơ tài khoản.</p><p id="preferences-error" class="form-error" role="alert" hidden></p><div class="settings-submit"><button class="primary" type="submit">Lưu thông tin</button></div></form><section class="panel"><div class="panel-heading"><h2>${icon('sun')}Giao diện & thông báo</h2></div><label class="field"><span>Nền giao diện</span><select id="settings-theme">${[['light','Sáng'],['dark','Tối'],['amber','Đen hổ phách'],['moss','Rêu Lime']].map(([v,l])=>`<option value="${v}" ${document.documentElement.dataset.theme===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="switch-row"><span><strong>Thông báo thao tác</strong><small>Hiển thị thông báo nhỏ trong bản thử.</small></span><input type="checkbox" data-setting="toasts" ${s.toasts?'checked':''}></label><label class="switch-row"><span><strong>Chuyển động giao diện</strong><small>Hiệu ứng mở rộng thanh menu.</small></span><input type="checkbox" data-setting="motion" ${s.motion?'checked':''}></label></section><section class="panel"><div class="panel-heading"><h2>${icon('layers')}Dữ liệu thử nghiệm</h2></div><div class="settings-data"><div><strong>${state.orders.length}</strong><span>đơn hàng</span></div><div><strong>${state.vehicles.length}</strong><span>xe</span></div><div><strong>${state.drivers.length}</strong><span>tài xế</span></div></div><p class="section-note">Dữ liệu được lưu bằng trình duyệt này${storageFailed?' · Hiện chưa lưu được thay đổi.':'.'}</p><div class="workspace-actions">${actionButton('Tải dữ liệu JSON','export-json',null,'secondary')}${actionButton('Khôi phục mẫu','reset-confirm',null,'secondary danger-text')}</div></section><section class="panel connection-panel"><div class="panel-heading"><h2>${icon('pin')}Kết nối</h2></div><div class="connection-row"><strong>Máy chủ / tài khoản</strong><span>Chưa kết nối</span></div><div class="connection-row"><strong>GPS / bản đồ</strong><span>Sơ đồ mẫu</span></div><div class="connection-row"><strong>Đề xuất phân xe</strong><span>Phương án mẫu</span></div><p class="section-note">Các thao tác không gửi thông báo tới tài xế hoặc tạo chuyến ngoài hệ thống.</p></section></div>`;}
  function renderDispatch(){const o=selectedOrder();if(!o){$('#dispatch-order').innerHTML='<option>Chưa có đơn hàng</option>';$('.order-card h3').textContent='Chưa có đơn hàng để phân xe';$('.order-card p').textContent='Tạo đơn mới ở mục Đơn hàng.';$('.vehicles').replaceChildren();$('#assign').disabled=true;$('#suggest').disabled=true;$('#dispatch-note').textContent='Không có đơn hàng đang hoạt động trong dữ liệu mẫu.';$$('[data-summary]').forEach(el=>el.querySelector('strong').textContent='0');$('.trips tbody').replaceChildren();$('#timeline').innerHTML=timeline(3).replace(/^<ol[^>]*>|<\/ol>$/g,'');return;}state.selectedOrder=o.id;const options=candidates(o),available=options.some(v=>v.plate===state.selectedVehicle);if(o.status==='pending'&&!available)state.selectedVehicle=options[0]?.plate||'';
    const picker=$('#dispatch-order');picker.innerHTML=state.orders.filter(x=>x.status!=='cancelled').map(x=>`<option value="${esc(x.id)}" ${o.id===x.id?'selected':''}>${esc(x.id)} · ${esc(x.material)} · ${labels[x.status]}</option>`).join('');
    $('.order-card h3').innerHTML=`${esc(o.id)} <span>·</span> ${esc(o.material)} <span>(${o.quantity} tấn)</span>`;
    $('.order-card p').innerHTML=`${icon('pin')}${esc(o.from)}<span class="route-arrow">→</span>${icon('pin')}${esc(o.to)}`;
    $('.vehicles').innerHTML=o.status==='pending'?(options.slice(0,3).map((v,i)=>`<button class="vehicle ${v.plate===state.selectedVehicle?'selected':''}" aria-pressed="${v.plate===state.selectedVehicle}" data-vehicle="${esc(v.plate)}"><span class="rank">${i+1}</span>${icon('truck')}<strong>${esc(v.plate)}</strong><span class="eta">≈ ${v.eta} phút</span></button>`).join('')||'<p class="subtle">Không có xe sẵn sàng phù hợp trong dữ liệu mẫu. Kiểm tra đội xe hoặc chọn đơn khác.</p>'):`<div class="assigned-summary">${icon('truck')}<strong>${esc(o.plate||'Chưa có xe')}</strong>${badge(o.status)}</div>`;
    $('#assign').disabled=o.status==='pending'&&!options.length;$('#assign').innerHTML=o.status==='pending'?'Duyệt phân công <span>→</span>':'Xem phân công <span>→</span>';$('#suggest').disabled=o.status!=='pending'||!options.length;
    $('#dispatch-note').textContent=o.status==='pending'?(state.selectedVehicle?'Đang chọn xe '+state.selectedVehicle+' · Phương án mẫu, chưa kiểm tra vận hành thực tế.':'Chưa có xe phù hợp trong dữ liệu mẫu.'):'Đơn '+o.id+' · '+labels[o.status]+'. Thao tác được lưu trong trình duyệt.';
    const c=counts(),summary={'Đơn chờ':c.pending,'Chuyến đang chạy':c.running,'Xe sẵn sàng':c.ready,'Cần xử lý':alerts().length};$$('[data-summary]').forEach(el=>el.querySelector('strong').textContent=summary[el.dataset.summary]);
    const recent=state.orders.filter(x=>['running','completed','assigned'].includes(x.status)).slice(0,3);$('.trips tbody').innerHTML=recent.map(x=>`<tr><td>${actionButton(esc(x.id),'detail-order',x.id)}</td><td>${esc(x.material)} <span>(${x.quantity} tấn)</span></td><td>${esc(x.from)} → ${esc(x.to)}</td><td>${badge(x.status)}</td><td>${esc(x.slot||'—')}</td></tr>`).join('');
    $('#timeline').innerHTML=timeline(3).replace(/^<ol[^>]*>|<\/ol>$/g,'');
    const texts=$$('.gps .map-art text');if(texts[0])texts[0].textContent=o.from;if(texts[1])texts[1].textContent=o.to;$('.gps .map-art').setAttribute('aria-label','Sơ đồ hành trình mẫu: '+o.from+' đến '+o.to);
    $('.gps .map-art').style.transform=`scale(${mapZoom})`;$('#map-out').disabled=mapZoom<=1;$('#map-in').disabled=mapZoom>=1.6;
  }
  function centerMobileNav(){if(innerWidth<=600){const nav=$('.sidebar nav'),active=nav.querySelector('[aria-current=page]');if(active)nav.scrollLeft=active.offsetLeft-nav.offsetLeft-(nav.clientWidth-active.offsetWidth)/2;}}
  function render(){
    const focusedId=$('#workspace-view').contains(document.activeElement)?document.activeElement.id:null;
    document.documentElement.dataset.motion=state.settings.motion?'on':'off';$('.brand-label').textContent=state.settings.company;$('.brand').setAttribute('aria-label',state.settings.company);$('.account').setAttribute('aria-label','Tài khoản '+state.settings.dispatcher);$('.account-name').textContent=state.settings.dispatcher;
    $('.crumb').innerHTML=`${icon('home')}<span>/</span>${routes[page]}`;
    $$('[data-page]').forEach(button=>{const active=button.dataset.page===routes[page];button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});
    centerMobileNav();
    $('#dispatch-view').hidden=page!=='dispatch';$('#workspace-view').hidden=page==='dispatch';
    if(page==='dispatch')renderDispatch();else{$('#workspace-view').innerHTML=({overview,orders:ordersView,fleet:fleetView,gps:gpsView,reports:reportsView,settings:settingsView})[page]();if(page==='gps')$('.fleet-map').style.transform=`scale(${gpsZoom})`;}
    document.title=routes[page]+' — Fleet Autopilot · Bản thử';
    $$('#workspace-view .table-wrap').forEach(w=>{w.tabIndex=0;w.setAttribute('role','region');w.setAttribute('aria-label','Bảng dữ liệu có thể cuộn ngang');const hint=document.createElement('p');hint.className='table-scroll-hint';hint.textContent='Cuộn ngang để xem đầy đủ →';hint.hidden=w.scrollWidth<=w.clientWidth+1;w.insertAdjacentElement('beforebegin',hint);});
    if(focusedId)document.getElementById(focusedId)?.focus({preventScroll:true});
    window.dispatchEvent(new Event('fleet:render'));
  }
  function details(o){if(!o)return;const extra=htmlNode(`<dl class="detail-grid"><div><dt>Khách hàng</dt><dd>${esc(o.customer)}</dd></div><div><dt>Vật liệu / khối lượng</dt><dd>${esc(o.material)} · ${o.quantity} tấn</dd></div><div><dt>Điểm lấy</dt><dd>${esc(o.from)}</dd></div><div><dt>Điểm giao</dt><dd>${esc(o.to)}</dd></div><div><dt>Ngày / giờ giao mẫu</dt><dd>${date(o.day)} · ${esc(o.slot||'Chưa đặt giờ')}</dd></div><div><dt>Xe</dt><dd>${esc(o.plate||'Chưa phân xe')}</dd></div></dl><div class="trip-status"><span>Trạng thái mẫu</span>${badge(o.status)}</div>${o.note?`<p class="modal-copy">${esc(o.note)}</p>`:''}<div class="detail-actions">${o.status==='pending'?actionButton('Chỉnh sửa','edit-order',o.id,'secondary')+actionButton('Chuyển sang Điều phối →','dispatch-order',o.id,'primary'):o.status==='assigned'?actionButton('Bắt đầu chuyến mẫu','start-order',o.id,'primary'):o.status==='running'?actionButton('Hoàn thành chuyến mẫu','complete-order',o.id,'primary'):''}${o.status==='pending'?actionButton('Hủy đơn mẫu','cancel-order',o.id,'text-button danger-text'):''}</div>`);openModal('Chi tiết '+o.id,'Thông tin dùng để xem thử giao diện.',extra);}
  function vehicleDetail(v){if(!v)return;const o=activeOrder(v.plate),d=driver(v.driverId);openModal('Xe '+v.plate,'Thông tin và vị trí đều là dữ liệu mẫu.',htmlNode(`<dl class="detail-grid"><div><dt>Loại xe</dt><dd>${esc(v.type)}</dd></div><div><dt>Tải trọng mẫu</dt><dd>${v.capacity} tấn</dd></div><div><dt>Tài xế</dt><dd>${esc(d?.name||'Chưa gán')}</dd></div><div><dt>Đơn đang thực hiện</dt><dd>${esc(o?.id||'Chưa có')}</dd></div></dl><div class="detail-actions">${badge(vehicleStatus(v))}${badge(v.gps)}${actionButton('Chỉnh sửa thông tin','edit-vehicle',v.plate,'secondary')}${actionButton('Xem trên sơ đồ →','track-vehicle',v.plate,'primary')}</div>`));}
  function confirmAssignment(){const o=selectedOrder(),v=vehicle(state.selectedVehicle);if(!o){toast('Chưa có đơn hàng để phân xe.');return;}if(o.status!=='pending'){details(o);return;}if(!v||!candidates(o).includes(v)){toast('Vui lòng chọn xe sẵn sàng trong danh sách.');return;}const fragment=$('#assignment-review-template').content.cloneNode(true);fragment.querySelector('.review-id').textContent=o.id;fragment.querySelector('.review-material h3').textContent=o.material;fragment.querySelector('.review-weight strong').textContent=o.quantity;fragment.querySelectorAll('.review-route strong')[0].textContent=o.from;fragment.querySelectorAll('.review-route strong')[1].textContent=o.to;fragment.querySelector('[data-review-plate]').textContent=v.plate;
    openModal('Duyệt phân công','Kiểm tra đơn hàng và xe trước khi xác nhận.',fragment,()=>{if(o.status!=='pending'||!candidates(o).includes(v)){toast('Dữ liệu mẫu đã thay đổi. Chọn lại xe.');return false;}o.status='assigned';o.plate=v.plate;commit('Đã phân công mẫu '+v.plate+' cho '+o.id,o.from+' → '+o.to);toast('Đã lưu phân công mẫu trên trình duyệt.');});modal.classList.add('assignment-review');$('#cancel-modal').textContent='Quay lại';confirm.append(document.createTextNode(' →'));
  }
  const field=(label,name,value='',type='text',attrs='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
  function editForm(name,html,handler){const wrap=htmlNode(`<form id="editor-form" class="editor-form">${html}<p id="editor-error" class="form-error full-field" role="alert" hidden></p><button type="submit" hidden>Lưu</button></form>`);openModal(name,'Chỉnh sửa dữ liệu mẫu, chỉ lưu trong trình duyệt.',wrap,()=>{const f=$('#editor-form');if(!f.reportValidity())return false;return handler(new FormData(f));},'Lưu dữ liệu mẫu');$('#editor-form').onsubmit=e=>{e.preventDefault();confirm.click();};}
  function editOrder(id){const o=order(id);if(o&&o.status!=='pending'){toast('Chỉ chỉnh sửa đơn chờ trong bản thử.');return;}editForm(o?'Chỉnh sửa '+o.id:'Tạo đơn hàng mẫu',field('Khách hàng','customer',o?.customer,'text','required maxlength="100"')+field('Vật liệu','material',o?.material,'text','required maxlength="80"')+field('Khối lượng (tấn)','quantity',o?.quantity||'','number','required min="0.1" max="1000" step="0.1"')+field('Điểm lấy','from',o?.from,'text','required maxlength="150"')+field('Điểm giao','to',o?.to,'text','required maxlength="150"')+field('Ngày giao mẫu','day',o?.day||sampleDay,'date','required')+field('Giờ hẹn mẫu','slot',o?.slot||'','time')+`<label class="field full-field"><span>Ghi chú</span><textarea name="note" rows="2" maxlength="500">${esc(o?.note||'')}</textarea></label>`,data=>{const values=Object.fromEntries(data);for(const k of ['customer','material','from','to'])if(!values[k].trim()){formError('Vui lòng nhập '+({customer:'khách hàng',material:'vật liệu',from:'điểm lấy',to:'điểm giao'})[k]+'.');return false;}values.quantity=Number(values.quantity);if(o)Object.assign(o,values);else{const n=Math.max(1046,...state.orders.map(x=>Number(x.id.replace(/\D/g,''))||0))+1;state.orders.unshift({...values,id:'ĐH-'+n,status:'pending',plate:''});}commit(o?'Đã sửa đơn mẫu '+o.id:'Đã tạo đơn hàng mẫu',values.material+' · '+values.quantity+' tấn');toast('Đã lưu đơn hàng mẫu.');});}
  function editVehicle(plate){const v=vehicle(plate),busy=v&&activeOrder(v.plate);editForm(v?'Chỉnh sửa xe '+v.plate:'Thêm xe mẫu',field('Biển số','plate',v?.plate,'text',`required maxlength="20" ${v?'readonly':''}`)+field('Loại xe','type',v?.type||'Xe ben','text','required maxlength="60"')+field('Tải trọng mẫu (tấn)','capacity',v?.capacity||30,'number',`required min="1" max="200" step="1" ${busy?'readonly':''}`)+`<label class="field"><span>Tài xế</span><select name="driverId" ${busy?'disabled':''}><option value="">Chưa gán</option>${state.drivers.filter(d=>d.id===v?.driverId||!state.vehicles.some(x=>x.driverId===d.id)).map(d=>`<option value="${esc(d.id)}" ${v?.driverId===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><label class="field full-field"><span>Tình trạng xe</span><select name="availability" ${busy?'disabled':''}><option value="ready">Sẵn sàng</option><option value="maintenance" ${v?.availability==='maintenance'?'selected':''}>Bảo trì</option></select>${busy?'<small>Xe có đơn đang thực hiện; tải trọng, tài xế và tình trạng được giữ nguyên trong bản thử.</small>':''}</label>`,data=>{const values=Object.fromEntries(data);values.plate=values.plate.trim().toUpperCase();if(!values.plate||!values.type.trim()){formError('Vui lòng nhập biển số và loại xe.');return false;}if(!v&&state.vehicles.some(x=>x.plate===values.plate)){formError('Biển số đã có trong dữ liệu mẫu.');return false;}values.capacity=Number(values.capacity);if(busy){values.availability=v.availability;values.driverId=v.driverId;values.capacity=v.capacity;}if(v)Object.assign(v,values);else state.vehicles.push({...values,eta:30,gps:'offline',x:320,y:160,updated:null});commit(v?'Đã cập nhật xe mẫu':'Đã thêm xe mẫu',values.plate);toast('Đã lưu thông tin xe.');});}
  function editDriver(id){const d=driver(id);editForm(d?'Chỉnh sửa tài xế':'Thêm tài xế mẫu',field('Tên hiển thị','name',d?.name,'text','required maxlength="80"')+field('Liên hệ (không bắt buộc)','phone',d?.phone,'tel','maxlength="30"')+`<label class="field full-field"><span>Tình trạng</span><select name="status"><option value="active">Đang làm việc</option><option value="off" ${d?.status==='off'?'selected':''}>Tạm nghỉ</option></select></label>`,data=>{const values=Object.fromEntries(data);if(!values.name.trim()){formError('Vui lòng nhập tên tài xế.');return false;}const attached=state.vehicles.find(v=>v.driverId===id);if(values.status==='off'&&attached&&activeOrder(attached.plate)){formError('Tài xế đang gắn với xe có chuyến mẫu chưa hoàn thành.');return false;}if(d)Object.assign(d,values);else state.drivers.push({...values,id:'TX-'+(Math.max(0,...state.drivers.map(x=>Number(x.id.replace(/\D/g,''))||0))+1)});commit(d?'Đã sửa tài xế mẫu':'Đã thêm tài xế mẫu',values.name);toast('Đã lưu tài xế.');});}
  function transitionOrder(id,next){const o=order(id),expected={running:'assigned',completed:'running',cancelled:'pending'}[next];if(!o||o.status!==expected)return;openModal(next==='cancelled'?'Hủy đơn mẫu '+id:next==='running'?'Bắt đầu chuyến mẫu':'Hoàn thành chuyến mẫu',`${o.id} · ${o.material} · ${o.quantity} tấn\n${o.from} → ${o.to}\n\nThao tác chỉ cập nhật dữ liệu trong trình duyệt.`,null,()=>{o.status=next;commit('Đơn '+o.id+': '+labels[next],o.plate||o.material);toast('Đã cập nhật trạng thái mẫu.');});}
  function csv(name,rows){download(name,'\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+\-@]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');}
  function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã tạo tệp dữ liệu mẫu.');}
  function exportOrders(list,name){csv(name,[['Mã đơn','Khách','Vật liệu','Tấn','Điểm lấy','Điểm giao','Ngày','Giờ','Trạng thái','Xe'],...list.map(o=>[o.id,o.customer,o.material,o.quantity,o.from,o.to,o.day,o.slot,labels[o.status],o.plate])]);}
  function reset(){state=seed();orderQuery='';orderStatus='all';orderDay='';fleetQuery='';fleetFilter='all';gpsPlate=state.vehicles[0].plate;mapZoom=1;gpsZoom=1;try{localStorage.removeItem('fleet-autopilot-ui-demo-v1');}catch{}save();render();toast('Đã khôi phục dữ liệu mẫu.');}
  function actions(action,id){
    if(action==='noop')return;
    if(action.startsWith('go-')){if(modal.open)closeModal();const target=action.slice(3);if(target==='orders-pending'){orderStatus='pending';setPage('orders',{focus:true});}else setPage(target,{focus:true});return;}
    switch(action){
      case 'new-order':editOrder();break;case 'edit-order':editOrder(id);break;case 'detail-order':details(order(id));break;
      case 'dispatch-order':if(modal.open)closeModal();state.selectedOrder=id;save();setPage('dispatch',{focus:true});break;
      case 'start-order':transitionOrder(id,'running');break;case 'complete-order':transitionOrder(id,'completed');break;case 'cancel-order':transitionOrder(id,'cancelled');break;
      case 'new-vehicle':editVehicle();break;case 'edit-vehicle':editVehicle(id);break;case 'detail-vehicle':vehicleDetail(vehicle(id));break;case 'new-driver':editDriver();break;case 'edit-driver':editDriver(id);break;
      case 'fleet-tab':fleetTab=id;fleetQuery='';render();break;
      case 'track-vehicle':if(modal.open)closeModal();gpsPlate=id;gpsFilter='all';setPage('gps',{focus:true});break;
      case 'gps-select':gpsPlate=id;render();break;
      case 'gps-in':gpsZoom=Math.min(1.6,+(gpsZoom+.2).toFixed(1));render();break;case 'gps-out':gpsZoom=Math.max(1,+(gpsZoom-.2).toFixed(1));render();break;
      case 'simulate-gps':state.vehicles.forEach(v=>{if(v.gps!=='offline'){v.x=80+(v.x+23)%450;v.y=55+(v.y+11)%180;v.updated=stamp();v.gps='fresh';}});commit('Đã cập nhật vị trí mô phỏng','Không sử dụng dữ liệu GPS thực.');toast('Đã thay đổi vị trí mẫu trên sơ đồ.');break;
      case 'clear-order-filters':orderQuery='';orderStatus='all';orderDay='';render();break;
      case 'export-orders':exportOrders(state.orders.filter(o=>(orderStatus==='all'||o.status===orderStatus)&&(!orderDay||o.day===orderDay)&&norm(Object.values(o).join(' ')).includes(norm(orderQuery))),'don-hang-mau.csv');break;
      case 'export-fleet':csv('doi-xe-mau.csv',[['Biển số','Loại xe','Tải mẫu (tấn)','Tài xế','Trạng thái'],...state.vehicles.map(v=>[v.plate,v.type,v.capacity,driver(v.driverId)?.name,labels[vehicleStatus(v)]])]);break;
      case 'export-reports':if(reportFrom>reportTo){toast('Vui lòng kiểm tra khoảng ngày báo cáo.');return;}exportOrders(reportData(),'bao-cao-van-chuyen-mau.csv');break;
      case 'export-drivers':csv('tai-xe-mau.csv',[['Mã tài xế','Tên','Liên hệ','Xe đang gắn','Tình trạng'],...state.drivers.map(d=>[d.id,d.name,d.phone,state.vehicles.find(v=>v.driverId===d.id)?.plate||'',labels[d.status]])]);break;
      case 'export-json':download('fleet-autopilot-du-lieu-mau.json',JSON.stringify(state,null,2),'application/json');break;
      case 'reset-confirm':openModal('Khôi phục dữ liệu mẫu','Các đơn, xe, tài xế, cài đặt và lịch sử mẫu đã sửa sẽ được thay bằng bộ dữ liệu ban đầu. Nền đang chọn được giữ nguyên.',null,reset,'Khôi phục mẫu');break;
    }
  }
  document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)actions(el.dataset.action,el.dataset.id);const vb=e.target.closest('[data-vehicle]');if(vb){state.selectedVehicle=vb.dataset.vehicle;save();renderDispatch();}});
  document.addEventListener('keydown',e=>{const marker=e.target.closest('.fleet-marker');if(marker&&['Enter',' '].includes(e.key)){e.preventDefault();actions('gps-select',marker.dataset.id);}});
  function liveFilter(id,value){const pos=document.activeElement?.selectionStart;const mapping={'orders-query':()=>orderQuery=value,'fleet-query':()=>fleetQuery=value};mapping[id]();render();const el=$('#'+id);el.focus({preventScroll:true});if(pos!==null)el.setSelectionRange(pos,pos);}
  document.addEventListener('input',e=>{if(e.target.closest('#editor-form,#preferences-form')){const error=$('#editor-error')||$('#preferences-error');if(error)error.hidden=true;}if(['orders-query','fleet-query'].includes(e.target.id))liveFilter(e.target.id,e.target.value);});
  document.addEventListener('change',e=>{const el=e.target;switch(el.id){case 'orders-status':orderStatus=el.value;render();break;case 'orders-day':orderDay=el.value;render();break;case 'fleet-status':fleetFilter=el.value;render();break;case 'gps-filter':gpsFilter=el.value;render();break;case 'report-from':reportFrom=el.value||'0000-01-01';render();break;case 'report-to':reportTo=el.value||'9999-12-31';render();break;case 'settings-theme':$('#theme-select').value=el.value;$('#theme-select').dispatchEvent(new Event('change',{bubbles:true}));break;}
    if(el.dataset.setting){state.settings[el.dataset.setting]=el.checked;save();render();}
    if(el.matches('[data-theme-option],#theme-select')&&page==='settings')render();
  });
  document.addEventListener('submit',e=>{if(e.target.id==='preferences-form'){e.preventDefault();const f=e.target;if(!f.reportValidity())return;const data=new FormData(f),company=data.get('company').trim(),dispatcher=data.get('dispatcher').trim();if(!company||!dispatcher){formError('Vui lòng nhập tên hiển thị.');return;}state.settings.company=company;state.settings.dispatcher=dispatcher;save();render();toast('Đã lưu thông tin hiển thị.');}});
  $('#dispatch-order').onchange=e=>{state.selectedOrder=e.target.value;save();renderDispatch();};$('#assign').onclick=confirmAssignment;
  $('#suggest').onclick=()=>{const options=candidates(selectedOrder());if(options.length){state.selectedVehicle=options[0].plate;save();renderDispatch();toast('Đã chọn phương án mẫu theo thời gian minh họa.');}};
  $('#all-trips').onclick=()=>{orderStatus='all';setPage('orders',{focus:true});};
  $$('[data-summary]').forEach(el=>el.onclick=()=>{if(el.dataset.summary==='Đơn chờ'){orderStatus='pending';setPage('orders',{focus:true});}else if(el.dataset.summary==='Chuyến đang chạy')setPage('gps',{focus:true});else if(el.dataset.summary==='Xe sẵn sàng')setPage('fleet',{focus:true});else showAttention();});
  $('#notifications').onclick=()=>openModal('Hoạt động gần đây','Các thay đổi mẫu trong trình duyệt này.',htmlNode(timeline(8)));
  $('#account').onclick=()=>{openModal(state.settings.dispatcher,'Không gian thử nghiệm · Chưa đăng nhập tài khoản thực.',htmlNode(`<div class="detail-actions">${actionButton('Mở cài đặt →','go-settings',null,'primary')}</div>`));};
  $('#reset-demo').onclick=()=>actions('reset-confirm');
  $('.brand').onclick=e=>{e.preventDefault();setPage('overview',{focus:true});};
  $('#map-in').onclick=()=>{mapZoom=Math.min(1.6,+(mapZoom+.2).toFixed(1));renderDispatch();};$('#map-out').onclick=()=>{mapZoom=Math.max(1,+(mapZoom-.2).toFixed(1));renderDispatch();};
  function searchResults(value){const list=state.orders.filter(o=>norm(Object.values(o).join(' ')).includes(norm(value)));$('#search-results').innerHTML=list.length?list.map(o=>`<button class="dialog-row" data-search-order="${esc(o.id)}"><span><strong>${esc(o.id)} · ${esc(o.material)}</strong><small>${esc(o.from)} → ${esc(o.to)}</small></span>${badge(o.status)}</button>`).join(''):'<p class="empty">Không tìm thấy đơn hàng phù hợp.</p>';}
  $('#search').placeholder='Tìm đơn, xe, hành trình…';$('#search').setAttribute('aria-label','Tìm đơn hàng theo mã, vật liệu, hành trình hoặc xe');$('#search').oninput=e=>{orderQuery=e.target.value;orderStatus='all';orderDay='';if(page!=='orders')setPage('orders');else render();$('#search').focus({preventScroll:true});};
  $('#open-search').onclick=()=>{searchResults('');searchModal.showModal();$('#mobile-search-input').value='';$('#mobile-search-input').focus();};$('#mobile-search-input').oninput=e=>searchResults(e.target.value);$('#close-search').onclick=()=>searchModal.close();
  $('#search-results').onclick=e=>{const button=e.target.closest('[data-search-order]');if(button){searchModal.close();details(order(button.dataset.searchOrder));}};
  document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!modal.open&&!searchModal.open){e.preventDefault();if($('#search').getClientRects().length)$('#search').focus();else $('#open-search').click();}});
  window.addEventListener('resize',()=>{centerMobileNav();$$('#workspace-view .table-wrap').forEach(w=>{if(w.previousElementSibling?.classList.contains('table-scroll-hint'))w.previousElementSibling.hidden=w.scrollWidth<=w.clientWidth+1;});});
  document.fonts.ready.then(centerMobileNav);
  // Theme events run after theme.js has applied the selected palette.
  document.addEventListener('click',e=>{if(e.target.closest('[data-theme-option]')&&page==='settings')render();});
  window.FleetPreview={snapshot:()=>state,openModal,toast,render};
  render();
})();
